style.css:
@-moz-document domain("youtube.com") {
/* Bloodlust: Victorian Nightmare — YouTube */

:root {
  --my-black: #080609;
  --my-panel: rgba(12, 8, 12, 0.88);
  --my-red: #850018;
  --my-crimson: #b00025;
  --my-dark-red: #39000d;
  --my-text: #e8dfe3;
  --my-muted: #a58c94;
}

/* gothic wallpaper */
html,
body,
ytd-app {
  background-color: var(--my-black) !important;
  background-image: url("https://i.postimg.cc/tgRYBGJH/gothic.jpg") !important;
  background-position: center center !important;
  background-size: cover !important;
  background-attachment: fixed !important;
  background-repeat: no-repeat !important;
}

/* transparent content */
#content,
#page-manager,
ytd-browse,
ytd-search,
ytd-watch-flexy {
  background: transparent !important;
}

/* header */
ytd-masthead,
#masthead-container {
  background: rgba(8, 6, 9, 0.96) !important;
  border-bottom: 1px solid var(--my-dark-red) !important;
}

/* navigation */
ytd-mini-guide-renderer,
ytd-guide-renderer,
#guide-content {
  background: rgba(10, 7, 10, 0.94) !important;
}

/* search */
#center input,
ytd-searchbox {
  background: #130c11 !important;
  border: 1px solid #510b20 !important;
  color: var(--my-text) !important;
}

/* category buttons */
yt-chip-cloud-chip-renderer {
  background: rgba(15, 9, 13, 0.95) !important;
  color: var(--my-muted) !important;
  border: 1px solid #45101c !important;
  border-radius: 4px !important;
}

yt-chip-cloud-chip-renderer[aria-selected="true"] {
  background: var(--my-red) !important;
  color: white !important;
}

/* thumbnails */
ytd-thumbnail,
#thumbnail {
  border-radius: 5px !important;
  overflow: hidden !important;
}

/* video titles */
#video-title {
  color: var(--my-text) !important;
}

#video-title:hover {
  color: var(--my-crimson) !important;
}

/* video information */
#metadata,
#meta {
  color: var(--my-muted) !important;
}

/* buttons */
yt-button-shape button {
  border-radius: 4px !important;
}

/* red accents */
a:hover {
  color: var(--my-crimson) !important;
}

/* gothic borders */
ytd-rich-section-renderer {
  border-color: #420b19 !important;
}

/* scrollbar */
::-webkit-scrollbar {
  width: 8px !important;
}

::-webkit-scrollbar-track {
  background: #080609 !important;
}

::-webkit-scrollbar-thumb {
  background: #680016 !important;
  border-radius: 4px !important;
}
}
